+---
+setup:
+  - do:
+      indices.create:
+        index: geometries
+        body:
+          settings:
+            number_of_shards: 1
+            number_of_replicas: 1
+          mappings:
+            runtime:
+              geometry_from_doc_value:
+                type: geo_shape
+                script:
+                  source: |
+                    GeoBoundingBox bbox = doc["geometry"].getBoundingBox();
+                    emit("BBOX(" + bbox.topLeft().getLon() + "," + bbox.topLeft().getLat() + "," + bbox.bottomRight().getLon() + "," + bbox.bottomRight().getLat() + ")");
+              geometry_from_source:
+                type: geo_shape
+                script:
+                  source: |
+                    emit(params._source.geometry);
+            properties:
+              timestamp:
+                type: date
+              geometry:
+                type: geo_shape
+  - do:
+      bulk:
+        index: geometries
+        refresh: true
